import React, { ReactChildren, ReactElement, ReactNode } from "react";
import {
  useField,
  VoidField,
} from "@formily/react";
import toArray from "rc-util/es/Children/toArray";
import { TableProps } from "@arco-design/web-react";
import { ArrayField as ArrayFieldType } from "@formily/core";
import { isArray } from "@arco-design/web-react/es/_util/is";
import { isPlainObj } from "@formily/shared";
import FormItemLabel from "../../FormItem/FormLabel";

const parseJSXColumnsChildren = (children: ReactChildren) => {
  const arraychildren = isArray(children)
    ? children
    : React.Children.toArray?.(children);
  return arraychildren;
};

/**
 * 解析 ArrayTable 的 Columns
 */
export const useParseJSXColumns = (children: ReactNode) => {
  const arrayField: ArrayFieldType = useField();
  // 解析出所有的 ArrayTableColumns
  const childNodes = toArray(children, { keepEmpty: false });
  const columnsNodes: ReactElement[] = [];
  const additionNodes: ReactElement[] = [];
  childNodes.forEach((child) => {
    const childPropsComponent = (child as ReactElement)?.props?.component;
    // 对应 field.component 属性
    const [component] = childPropsComponent || [];
    switch (component?.displayName) {
      case "ArrayTableColumn":
        columnsNodes.push(child);
        break;
      case "ArrayTableAddition":
        additionNodes.push(child);
        break;
      default:
        break;
    }
  });
  const columns = columnsNodes.reduce((buf, node, key) => {
    const { name, component, children } = node.props;
    const [_, columnProps] = component || [];

    // 查询到虚拟的 column 节点，判断显示是否生成 columns
    const field = arrayField.query(arrayField.address.concat(name)).take();
    const display = field?.display || "visible";
    if (display !== "visible") {
      return buf;
    }
    return buf?.concat({
      ...columnProps,
      key,
      dataIndex: name,
      render: (_: any) => {
        return parseJSXColumnsChildren(children);
      },
      // 添加React.isValidElement兼容存量代码为ReactNode情况，否则会进入到isPlainObj
      title: React.isValidElement(columnProps.title) ? columnProps.title : isPlainObj(columnProps.title) ? <FormItemLabel showColon={false} requiredSymbol={true} {...columnProps.title}></FormItemLabel> : columnProps.title
    });
  }, [] as TableProps<any>["columns"]);

  // 用于接管列的虚拟节点，在界面上不显示
  const sourceColumns = columnsNodes.map((node, index) => {
    return React.cloneElement(node, { component: null, index }, null);
  });

  return { columns, addition: additionNodes, sourceColumns };
};
